        /*
            <div {{did-insert this.addSponsor this.isAddSponsorOpen}} {{did-update this.addSponsor this.isAddSponsorOpen}}>
          	<UiSlidePane @slideOn={{this.isViewSponsorMode}} @activeFace="view-sponsor">
          		<UiSlideFace
          			@actionText={{if this.event.sponsorCrudOperations.update (t "label.edit")}}
          			@done={{fn this.switchToEditSponsor}}
          			@name="view-sponsor"
          			@face-title={{t "label.sponsor.details"}}
          		>
          			<ViewSponsor
          				@defaultSponsorshipType={{this.defaultSponsorshipType}}
          				@sponsorshipSetting={{this.sponsorshipSetting}}
          				@userLanguage={{this.userLanguage}}
          				@sponsor={{this.viewingSponsor}}
          				@sponsorFormItems={{this.parentContext.sponsorFormItems}}
          				@event={{this.event}}
          				@contactFormProto={{contactFormProto}}
          			/>
          		</UiSlideFace>
          	</UiSlidePane>
          </div>
          <div>
          	<h4 class="page-header">
          		{{t "label.all.sponsors"}}
          		{{#if this.sponsors.length}}
          			({{this.sponsors.length}})
          		{{/if}}
          	</h4>
          </div>
          
          {{#if this.sponsors.length}}
          	<PlanLimitNotifyMessage @featureName="sponsors" @items={{this.sponsorsList}} />
          
          	<div class="uls-data-view pg-no-title">
          		<div class="data-container">
          			<div class="uls-filter-menu m-size mgb4">
          				<div class="left-menu">
          					<div class="menu-item">
          						<div class="uls-icon-input left wt200">
          							<i class="search-icon bs-icons1 ip-icon"></i>
          							<Input
          								class="uls-input m-size"
          								placeholder={{t "label.search"}}
          								@type="text"
          								@value={{this.searchString}}
          								@focus-out={{fn this.search}}
          							/>
          						</div>
          					</div>
          					{{#if this.sponsorshipTypes.length}}
          						<div class="menu-item">
          							<div class="center aligned">
          								<UiSelect
          									@content={{this.sponsorshipTypeListMenuContent}}
          									@skipSelection={{true}}
          									@value={{this.sponsorshipTypeFilter}}
          									@onValueSelected={{fn (mut sponsorshipTypeFilter)}}
          									@class="text-dropdown"
          									@iconClass="dropdown"
          								/>
          							</div>
          						</div>
          					{{/if}}
          					<LicenseFilterDropdown
          						@moduleLabel={{t "label.sponsors"}}
          						@items={{sponsorsList}}
          						@licenseFilterBool={{licenseFilterBool}}
          						@onChange={{this.licenseFilterBoolChange}}
          					/>
          				</div>
          
          				{{#if event.sponsorCrudOperations.create}}
          					<div class="right-menu">
          						<div class="menu-item">
          							<UiButton
          								@type="secondary"
          								@size="m-size"
          								@icon="export-icon mgr2"
          								@iconName="bs-icons1"
          								@customClassName="uls-button"
          								@label={{t "label.export"}}
          								@clicked={{fn exportSponsor}}
          								aria-label={{t "lbl.a11y.export" actionName=(t "label.sponsors")}}
          							/>
          						</div>
          						<div class="menu-item">
          							<PopupToggler @popup={{event.planProps.sponsorsLimitPopup}}>
          								<UiButton
          									@type="primary"
          									@size="m-size"
          									class="icon"
          									@customClassName="uls-button"
          									@clicked={{fn updateisAddSponsorOpen}}
          									@disabled={{event.planProps.sponsorsLimitPopup}}
          									@icon="add-icon-01 mgr1"
          									@iconName="bs-icons1"
          									@label={{t "label.add.sponsor"}}
          								/>
          							</PopupToggler>
          						</div>
          					</div>
          				{{/if}}
          			</div>
          			{{#if filteredSponsorsWithTypes.filteredSponsors.length}}
          				{{#each filteredSponsorsWithTypes.sponsorsWithTypes as |filteredSponsorsWithType index|}}
          					{{#if filteredSponsorsWithType.sponsors.length}}
          						<h6 class="mgt6 mgb3 text-uppercase medium-font">
          							{{#if (eq defaultSponsorshipType filteredSponsorsWithType.sponsorshipType)}}
          								{{defaultSponsorshipType}}
          							{{else}}
          								{{filteredSponsorsWithType.sponsorshipType.sponsorshipTypeTranslation.name}}
          							{{/if}}
          							({{filteredSponsorsWithType.sponsors.length}})
          						</h6>
          						<div class="uls-grid-listing secondary-list s-size">
          							{{#if (eq addHeaderForIndex index)}}
          								<div class="list list-head">
          									<div class="uls-grid fvc fhc gp2">
          										<div class="col-3">
          											<div class="medium-font">{{t "label.sponsor"}}</div>
          										</div>
          										<div class="col-4">
          											<div class="medium-font text capitalize">{{t "lbl.name.email"}}</div>
          										</div>
          										<div class="col-2 col-md-3">
          											<div class="medium-font">{{t "label.amount"}}</div>
          										</div>
          										<div class="col-3 col-md-2"></div>
          									</div>
          								</div>
          							{{/if}}
          							{{#sortable-js onUpdate=(fn reorderSponsors filteredSponsorsWithType.sponsors) items=filteredSponsorsWithType.sponsors as |sponsorList|}}
          								{{#each sponsorList as |sponsor|}}
          									{{#let sponsor.value as |item|}}
          										<div class="list position-relative">
          											<SponsorTile
          												@sponsor={{item}}
          												@sponsorCrudOperations={{event.sponsorCrudOperations}}
          												@editSponsor={{fn editSponsor}}
          												@viewSponsor={{fn viewSponsor}}
          												@assignBooth={{fn assignBooth}}
          												@selectedSponsorCurrencyCode={{sponsorshipSetting.currencyCode}}
          												@exhibitors={{exhibitors}}
          												@canAssignBooth={{canAssignBooth}}
          												@showMailDeliveryInfo={{fn parentContext.showMailDeliveryInfo}}
          												@contactFormProto={{contactFormProto}}/>
          										</div>
          									{{/let}}
          								{{/each}}
          							{{/sortable-js}}
          						</div>
          					{{/if}}
          				{{/each}}
          			{{else}}
          				<SearchResultsEmpty/>
          			{{/if}}
          		</div>
          	</div>
          {{else}}
          	<div class="uls-data-view old-ui-view">
          		<div class="data-container">
          			{{#if (and (eq sponsorshipTypes.length 0) event.canConfigureSponsorCategory)}}
          				<BackstageEmpty
          					@iconName="sponsor-icon"
          					@headerText="label.no.sponsor.yet"
          					@subHeaderText="message.sponsor.category.add"
          					@clickButton={{true}}
          					@clicked={{fn configureSponsorCategory}}
          					@actionText="label.configure.sponsor.category"
          				/>
          				<div class="text-center">
          					{{#if event.sponsorCrudOperations.create}}
          						<h5 class="text-uppercase">{{t "label.or"}}</h5>
          						<UiButton
          							@type="primary"
          							@size="xl-size"
          							@class="mgt3"
          							@clicked={{fn updateisAddSponsorOpen}}
          							@label="{{t 'label.add.sponsor'}}"
          						/>
          					{{/if}}
          				</div>
          			{{else if event.sponsorCrudOperations.create}}
          				<BackstageEmpty
          					@iconName="sponsor-icon"
          					@headerText="label.no.sponsor.yet"
          					@subHeaderText="message.sponsor.category.add"
          					@clickButton={{true}}
          					@clicked={{fn updateisAddSponsorOpen}}
          					@actionText="label.add.sponsor"
          				/>
          			{{else}}
          				<BackstageEmpty
          					@iconName="sponsor-icon"
          					@headerText="label.no.sponsor.yet"
          					@subHeaderText="message.sponsor.empty"
          				/>
          			{{/if}}
          		</div>
          	</div>
          {{/if}}
          {{partial "partials/sponsor/sponsor-editor-pane"}}
          
          {{#if parentContext.isLoading}}
          	{{ui-loading}}
          {{/if}}
          */
